// Accept Manual or Webhook body: creator_id, csvData (or xmlData).
const items = $input.all();
const out = [];
for (const item of items) {
  const b = item.json.body || item.json;
  const creatorId = b.creator_id || b.creatorId || 'unknown';
  const csvData = b.csvData || b.csv_data || '';
  const xmlData = b.xmlData || b.xml_data || '';
  const periodStart = b.period_start || b.periodStart || null;
  const periodEnd = b.period_end || b.periodEnd || null;
  out.push({
    json: {
      creator_id: creatorId,
      csvData: csvData,
      xmlData: xmlData,
      period_start: periodStart,
      period_end: periodEnd
    }
  });
}
return out.length ? out : [{ json: { creator_id: 'unknown', csvData: '', xmlData: '', period_start: null, period_end: null } }];

// Parse CSV from Associates report; output one item per row with creator_id and raw row.
const items = $input.all();
const out = [];
for (const item of items) {
  const { creator_id, csvData, period_start, period_end } = item.json;
  if (!csvData || typeof csvData !== 'string') continue;
  const lines = csvData.trim().split(/\r?\n/);
  if (lines.length < 2) continue;
  const headers = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, ''));
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i];
    if (!line.trim()) continue;
    const values = [];
    let current = '';
    let inQuotes = false;
    for (let j = 0; j < line.length; j++) {
      const c = line[j];
      if (c === '"') inQuotes = !inQuotes;
      else if (c === ',' && !inQuotes) { values.push(current.trim().replace(/^"|"$/g, '')); current = ''; }
      else current += c;
    }
    values.push(current.trim().replace(/^"|"$/g, ''));
    const row = { creator_id, period_start, period_end };
    headers.forEach((h, idx) => { if (values[idx] !== undefined) row[h] = values[idx]; });
    out.push({ json: row });
  }
}
return out.length ? out : [{ json: { error: 'No rows parsed', creator_id: items[0]?.json?.creator_id } }];

// Map each row to canonical creator earnings schema (see CREATOR-EARNINGS-CANONICAL-SCHEMA.md).
const items = $input.all();
const earningsKeys = ['Earnings','Commission','Commission Income','Bounty','Revenue','Order Total','Amount','Total','Payout','Shipped Revenue','Advertising Fee'];
const dateKeys = ['Date','Transaction Date','Earning Period Start Date','Earning Period End Date','Payment Date'];
const out = [];
for (const item of items) {
  const row = item.json;
  if (row.error) { out.push({ json: row }); continue; }
  const creator_id = row.creator_id || 'unknown';
  let normalized_earnings = null;
  let raw_type = 'commission';
  const allKeys = Object.keys(row).filter(k => !['creator_id','period_start','period_end'].includes(k));
  for (const key of earningsKeys) {
    const v = row[key];
    if (v !== undefined && v !== null && v !== '') {
      const num = typeof v === 'number' ? v : parseFloat(String(v).replace(/[^0-9.-]/g, ''));
      if (!isNaN(num)) { normalized_earnings = num; raw_type = key.toLowerCase().replace(/\s+/g,'_'); break; }
    }
  }
  if (normalized_earnings === null && allKeys.length) {
    for (const k of allKeys) {
      const v = row[k];
      if (v !== undefined && v !== null && v !== '') {
        const num = parseFloat(String(v).replace(/[^0-9.-]/g, ''));
        if (!isNaN(num)) { normalized_earnings = num; raw_type = k.toLowerCase().replace(/\s+/g,'_'); break; }
    }
  }
  }
  let period_start = row.period_start || null;
  let period_end = row.period_end || null;
  for (const key of dateKeys) {
    const v = row[key];
    if (v && !period_start && (key.includes('Start') || key === 'Date' || key === 'Transaction Date')) period_start = v;
    if (v && !period_end && (key.includes('End') || key === 'Payment Date')) period_end = v;
  }
  if (!period_start && row.Date) period_start = row.Date;
  if (!period_end && row.Date) period_end = row.Date;
  const currency = row.Currency || row.currency || 'USD';
  out.push({
    json: {
      creator_id,
      source_platform: 'amazon',
      period_start: period_start || new Date().toISOString().slice(0,10),
      period_end: period_end || new Date().toISOString().slice(0,10),
      normalized_earnings: normalized_earnings ?? 0,
      currency,
      raw_type,
      raw_payload: row,
      recorded_at: new Date().toISOString()
    }
  });
}
return out.length ? out : [{ json: { error: 'No normalized records' } }];
